")\n  blockedUsers          BlockedUser[]      @relation(\"UserBlocking\")\n  blockedByUsers        BlockedUser[]      @relation(\"UserBlocked\")\n  editorials            Editorial[] // New relation for user-created editorials\n  editorialLikes        EditorialLike[]\n  editorialComments     EditorialComment[]\n  friendshipsSent       Friendship[]       @relation(\"FriendshipRequester\")\n  friendshipsReceived   Friendship[]       @relation(\"FriendshipReceiver\")\n}\n\nmodel Closet {\n  id        String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name      String    @default(\"My Closet\")\n  userId    String    @unique @db.Uuid\n  createdAt DateTime  @default(now())\n  user      User      @relation(fields: [userId], references: [id])\n  listings  Listing[]\n}\n\nmodel Listing {\n  id                     String            @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  title                  String\n  description            String\n  imageUrls              String[]\n  isPrivate              Boolean           @default(false)\n  order                  Int               @default(0)\n  userId                 String            @db.Uuid\n  closetId               String            @db.Uuid\n  status                 ListingStatus     @default(ACTIVE)\n  createdAt              DateTime          @default(now())\n  updatedAt              DateTime          @updatedAt\n  favorites              Favorite[]        @relation(\"ListingFavorites\")\n  closet                 Closet            @relation(fields: [closetId], references: [id])\n  user                   User              @relation(fields: [userId], references: [id])\n  messages               Message[]\n  reviews                Review[]\n  tradePreferences       TradePreference[]\n  tradeRequestsInitiated TradeRequest[]    @relation(\"InitiatorListings\")\n  tags                   Tag[]             @relation(\"ListingTags\")\n  tradeRequestsReceived  TradeRequest[]    @relation(\"TargetListings\")\n}\n\nmodel TradePreference {\n  id        String   @id @default(cuid())\n  listingId String   @db.Uuid\n  userId    String   @db.Uuid\n  title     String\n  imageUrl  String\n  notes     String?\n  createdAt DateTime @default(now())\n  listing   Listing  @relation(fields: [listingId], references: [id])\n  user      User     @relation(fields: [userId], references: [id])\n}\n\nmodel TradeRequest {\n  id                String      @id @default(cuid())\n  fromUserId        String      @db.Uuid\n  toUserId          String      @db.Uuid\n  status            TradeStatus @default(PENDING)\n  message           String?\n  createdAt         DateTime    @default(now())\n  updatedAt         DateTime    @updatedAt\n  fromUser          User        @relation(\"TradeFrom\", fields: [fromUserId], references: [id])\n  toUser            User        @relation(\"TradeTo\", fields: [toUserId], references: [id])\n  initiatorListings Listing[]   @relation(\"InitiatorListings\")\n  targetListings    Listing[]   @relation(\"TargetListings\")\n  reviews           Review[]\n}\n\nmodel Tag {\n  id       String    @id @default(cuid())\n  name     String    @unique\n  listings Listing[] @relation(\"ListingTags\")\n}\n\nmodel Favorite {\n  id        String  @id @default(cuid())\n  userId    String  @db.Uuid\n  listingId String  @db.Uuid\n  listing   Listing @relation(\"ListingFavorites\", fields: [listingId], references: [id])\n  user      User    @relation(\"UserFavorites\", fields: [userId], references: [id])\n\n  @@unique([userId, listingId])\n}\n\nmodel Message {\n  id        String    @id @default(cuid())\n  fromId    String    @db.Uuid\n  toId      String    @db.Uuid\n  content   String\n  listingId String?   @db.Uuid\n  timestamp DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  isRead    Boolean   @default(false)\n  readAt    DateTime?\n  from      User      @relation(\"MessageFrom\", fields: [fromId], references: [id])\n  listing   Listing?  @relation(fields: [listingId], references: [id])\n  to        User      @relation(\"MessageTo\", fields: [toId], references: [id])\n}\n\nmodel Review {\n  id         String        @id @default(cuid())\n  rating     Int\n  comment    String?\n  reviewerId String        @db.Uuid\n  revieweeId String        @db.Uuid\n  listingId  String?       @db.Uuid\n  tradeId    String?\n  createdAt  DateTime      @default(now())\n  updatedAt  DateTime      @updatedAt\n  listing    Listing?      @relation(fields: [listingId], references: [id])\n  reviewee   User          @relation(\"ReviewTo\", fields: [revieweeId], references: [id])\n  reviewer   User          @relation(\"ReviewFrom\", fields: [reviewerId], references: [id])\n  trade      TradeRequest? @relation(fields: [tradeId], references: [id])\n\n  @@unique([reviewerId, tradeId])\n}\n\nmodel BlockedUser {\n  id        String   @id @default(cuid())\n  blockerId String   @db.Uuid\n  blockedId String   @db.Uuid\n  createdAt DateTime @default(now())\n  blocker   User     @relation(\"UserBlocking\", fields: [blockerId], references: [id])\n  blocked   User     @relation(\"UserBlocked\", fields: [blockedId], references: [id])\n\n  @@unique([blockerId, blockedId])\n}\n\nmodel Friendship {\n  id          String           @id @default(cuid())\n  requesterId String           @db.Uuid\n  receiverId  String           @db.Uuid\n  status      FriendshipStatus @default(PENDING)\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n  requester   User             @relation(\"FriendshipRequester\", fields: [requesterId], references: [id])\n  receiver    User             @relation(\"FriendshipReceiver\", fields: [receiverId], references: [id])\n\n  @@unique([requesterId, receiverId])\n}\n\nenum FriendshipStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n}\n\nenum TradeStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n  CANCELED\n}\n\nenum ListingStatus {\n  ACTIVE\n  SOLD\n  ARCHIVED\n}\n\nenum ProfileVisibility {\n  PUBLIC\n  PRIVATE\n  FRIENDS_ONLY\n}\n\nmodel Editorial {\n  id            String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  slug          String // Removed @unique since slug is now unique per user\n  title         String\n  subtitle      String?\n  content       String\n  excerpt       String?\n  image         String?\n  category      String\n  authorId      String   @db.Uuid // Changed from authorName to user ID\n  published     Boolean  @default(true) // Changed default to true since users can create\n  tags          String[]\n  isStaffPicked Boolean  @default(false) // New field for staff curation\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  // Relations\n  author   User               @relation(fields: [authorId], references: [id], onDelete: Cascade)\n  likes    EditorialLike[]\n  comments EditorialComment[]\n\n  // Ensure slug is unique per author\n  @@unique([authorId, slug])\n}\n\nmodel EditorialLike {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId      String    @db.Uuid\n  editorialId String    @db.Uuid\n  createdAt   DateTime  @default(now())\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  editorial   Editorial @relation(fields: [editorialId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, editorialId])\n}\n\nmodel EditorialComment {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  content     String\n  userId      String    @db.Uuid\n  editorialId String    @db.Uuid\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  editorial   Editorial @relation(fields: [editorialId], references: [id], onDelete: Cascade)\n}\n",
